text(await tools.apply_patch("*** Begin Patch
*** Add File: <private-path>/src/catalog.ts
+import { lstat, readdir } from "node:fs/promises";
+import { join, resolve } from "node:path";
+
+export type DebateEntry = {
+  id: string;
+  path: string;
+  hasTranscript: boolean;
+  hasFinalReport: boolean;
+};
+
+const DEBATE_ID = /^debate-[A-Za-z0-9][A-Za-z0-9._-]*$/;
+
+async function isRegularFile(path: string): Promise<boolean> {
+  try {
+    // lstat inspects the link itself, never its target.
+    return (await lstat(path)).isFile();
+  } catch (error) {
+    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
+    throw error;
+  }
+}
+
+/** Read the immediate saved-debate directories without following child symlinks. */
+export async function listDebates(root: string): Promise<DebateEntry[]> {
+  const absoluteRoot = resolve(root);
+  let children;
+  try {
+    children = await readdir(absoluteRoot, { withFileTypes: true });
+  } catch (error) {
+    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
+    throw error;
+  }
+
+  // Dirents classify symlinks as links, including links to directories. IDs are
+  // ASCII, so the default string sort gives code-point order without locale rules.
+  const ids = children
+    .filter((child) => child.isDirectory() && DEBATE_ID.test(child.name))
+    .map((child) => child.name)
+    .sort();
+
+  return Promise.all(ids.map(async (id) => {
+    const path = join(absoluteRoot, id);
+    const [hasTranscript, hasFinalReport] = await Promise.all([
+      isRegularFile(join(path, "debate.md")),
+      isRegularFile(join(path, "final-report.md")),
+    ]);
+    return { id, path, hasTranscript, hasFinalReport };
+  }));
+}
*** Add File: <private-path>/test/catalog.test.ts
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { mkdir, mkdtemp, readFile, rm, symlink, writeFile } from "node:fs/promises";
+import { join, relative } from "node:path";
+import { tmpdir } from "node:os";
+import { listDebates } from "../src/catalog.ts";
+
+async function fixture(t: { after: (fn: () => Promise<void>) => void }) {
+  const dir = await mkdtemp(join(tmpdir(), "disputatio-catalog-"));
+  t.after(() => rm(dir, { recursive: true, force: true }));
+  return dir;
+}
+
+test("catalog filters immediate directories and sorts IDs in code-point order", async (t) => {
+  const root = await fixture(t);
+  const ids = ["debate-a", "debate-A_1.2-", "debate-9", "debate-Z"];
+  for (const id of [...ids, "other", "debate-", "debate-.bad", "debate-_bad", "debate-a b", "debate-é"]) {
+    await mkdir(join(root, id));
+  }
+  await mkdir(join(root, "other", "debate-nested"));
+  await mkdir(join(root, "debate-a", "debate-nested"));
+  await writeFile(join(root, "debate-file"), "unrelated");
+  await writeFile(join(root, "debate-a", "debate.md"), "transcript");
+  await writeFile(join(root, "debate-A_1.2-", "final-report.md"), "report");
+  await writeFile(join(root, "debate-Z", "debate.md"), "");
+  await writeFile(join(root, "debate-Z", "final-report.md"), "");
+
+  assert.deepEqual(await listDebates(relative(process.cwd(), root)), [
+    { id: "debate-9", path: join(root, "debate-9"), hasTranscript: false, hasFinalReport: false },
+    { id: "debate-A_1.2-", path: join(root, "debate-A_1.2-"), hasTranscript: false, hasFinalReport: true },
+    { id: "debate-Z", path: join(root, "debate-Z"), hasTranscript: true, hasFinalReport: true },
+    { id: "debate-a", path: join(root, "debate-a"), hasTranscript: true, hasFinalReport: false },
+  ]);
+});
+
+test("catalog ignores directory links and does not count artifact links or directories", async (t) => {
+  const base = await fixture(t);
+  const root = join(base, "catalog");
+  const outside = join(base, "outside");
+  await mkdir(root);
+  await mkdir(outside);
+  await writeFile(join(outside, "debate.md"), "untouched transcript");
+  await writeFile(join(outside, "final-report.md"), "untouched report");
+  await symlink(outside, join(root, "debate-linked"));
+  await symlink(join(base, "missing"), join(root, "debate-dangling"));
+  for (const id of ["debate-artifacts", "debate-directories", "debate-broken"]) {
+    await mkdir(join(root, id));
+    for (const name of ["debate.md", "final-report.md"]) {
+      const path = join(root, id, name);
+      if (id === "debate-directories") await mkdir(path);
+      else await symlink(join(id === "debate-broken" ? base : outside, name), path);
+    }
+  }
+  await symlink(join(root, "debate-directories"), join(root, "debate-internal-link"));
+
+  assert.deepEqual(await listDebates(root), ["debate-artifacts", "debate-broken", "debate-directories"].map((id) => ({
+    id, path: join(root, id), hasTranscript: false, hasFinalReport: false,
