import { constants } from "node:fs";
import { lstat, open, readdir } from "node:fs/promises";
import { join, resolve } from "node:path";

export type DeterminationStatus = "resolved" | "needs-input" | "failed" | "unknown";

export type DebateEntry = {
  id: string;
  path: string;
  hasTranscript: boolean;
  hasFinalReport: boolean;
  determination: string | null;
  status: "unjudged" | DeterminationStatus;
};

const DEBATE_ID = /^debate-[A-Za-z0-9][A-Za-z0-9._-]*$/;

/** Catalog classification is deliberately stricter than the debate engine's parser. */
export function classifyDetermination(text: string): DeterminationStatus {
  const first = text.split(/\r?\n/).map((line) => line.trim()).find(Boolean) ?? "";
  if (first === "STATUS: RESOLVED") return "resolved";
  if (first === "STATUS: NEEDS_INPUT") return "needs-input";
  if (first.startsWith("Respondeo turn failed:")) return "failed";
  return "unknown";
}

async function determinationMetadata(path: string): Promise<Pick<DebateEntry, "determination" | "status">> {
  const candidates = (await readdir(path, { withFileTypes: true })).flatMap((file) => {
    if (!file.isFile()) return [];
    const match = /^respondeo(?:-([0-9]+))?\.md$/.exec(file.name);
    if (!match || match[0] !== file.name) return [];
    const version = BigInt(match[1] ?? "1");
    return version > 0n ? [{ name: file.name, version }] : [];
  });
  // BigInt preserves numerical ordering even beyond Number.MAX_SAFE_INTEGER.
  // Equal versions use filename order so filesystem enumeration never breaks ties.
  candidates.sort((a, b) => a.version === b.version
    ? (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)
    : a.version > b.version ? -1 : 1);

  for (const { name } of candidates) {
    let file;
    try {
      // Refuse a symlink even if the artifact changed after directory enumeration.
      // NONBLOCK also prevents a replacement FIFO from hanging the catalog.
      file = await open(join(path, name), constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
      if (!(await file.stat()).isFile()) continue;
      return { determination: name, status: classifyDetermination(await file.readFile("utf8")) };
    } catch (error) {
      if (["ENOENT", "ELOOP"].includes((error as NodeJS.ErrnoException).code ?? "")) continue;
      throw error;
    } finally {
      await file?.close();
    }
  }
  return { determination: null, status: "unjudged" };
}

async function isRegularFile(path: string): Promise<boolean> {
  try {
    // lstat inspects the link itself, never its target.
    return (await lstat(path)).isFile();
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

/** Read the immediate saved-debate directories without following child symlinks. */
export async function listDebates(root: string): Promise<DebateEntry[]> {
  const absoluteRoot = resolve(root);
  let children;
  try {
    children = await readdir(absoluteRoot, { withFileTypes: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }

  // Dirents classify symlinks as links, including links to directories. IDs are
  // ASCII, so the default string sort gives code-point order without locale rules.
  const ids = children
    .filter((child) => child.isDirectory() && DEBATE_ID.test(child.name))
    .map((child) => child.name)
    .sort();

  return Promise.all(ids.map(async (id) => {
    const path = join(absoluteRoot, id);
    const [hasTranscript, hasFinalReport, metadata] = await Promise.all([
      isRegularFile(join(path, "debate.md")),
      isRegularFile(join(path, "final-report.md")),
      determinationMetadata(path),
    ]);
    return { id, path, hasTranscript, hasFinalReport, ...metadata };
  }));
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdir, mkdtemp, readFile, rm, symlink, writeFile } from "node:fs/promises";
import { join, relative } from "node:path";
import { tmpdir } from "node:os";
import { classifyDetermination, listDebates } from "../src/catalog.ts";

async function fixture(t: { after: (fn: () => Promise<void>) => void }) {
  const dir = await mkdtemp(join(tmpdir(), "disputatio-catalog-"));
  t.after(() => rm(dir, { recursive: true, force: true }));
  return dir;
}

test("catalog filters immediate directories and sorts IDs in code-point order", async (t) => {
  const root = await fixture(t);
  const ids = ["debate-a", "debate-A_1.2-", "debate-9", "debate-Z"];
  for (const id of [...ids, "other", "debate-", "debate-.bad", "debate-_bad", "debate-a b", "debate-é"]) {
    await mkdir(join(root, id));
  }
  await mkdir(join(root, "other", "debate-nested"));
  await mkdir(join(root, "debate-a", "debate-nested"));
  await writeFile(join(root, "debate-file"), "unrelated");
  await writeFile(join(root, "debate-a", "debate.md"), "transcript");
  await writeFile(join(root, "debate-A_1.2-", "final-report.md"), "report");
  await writeFile(join(root, "debate-Z", "debate.md"), "");
  await writeFile(join(root, "debate-Z", "final-report.md"), "");

  assert.deepEqual(await listDebates(relative(process.cwd(), root)), [
    { id: "debate-9", path: join(root, "debate-9"), hasTranscript: false, hasFinalReport: false, determination: null, status: "unjudged" },
    { id: "debate-A_1.2-", path: join(root, "debate-A_1.2-"), hasTranscript: false, hasFinalReport: true, determination: null, status: "unjudged" },
    { id: "debate-Z", path: join(root, "debate-Z"), hasTranscript: true, hasFinalReport: true, determination: null, status: "unjudged" },
    { id: "debate-a", path: join(root, "debate-a"), hasTranscript: true, hasFinalReport: false, determination: null, status: "unjudged" },
  ]);
});

test("catalog ignores directory links and does not count artifact links or directories", async (t) => {
  const base = await fixture(t);
  const root = join(base, "catalog");
  const outside = join(base, "outside");
  await mkdir(root);
  await mkdir(outside);
  await writeFile(join(outside, "debate.md"), "untouched transcript");
  await writeFile(join(outside, "final-report.md"), "untouched report");
  await symlink(outside, join(root, "debate-linked"));
  await symlink(join(base, "missing"), join(root, "debate-dangling"));
  for (const id of ["debate-artifacts", "debate-directories", "debate-broken"]) {
    await mkdir(join(root, id));
    for (const name of ["debate.md", "final-report.md"]) {
      const path = join(root, id, name);
      if (id === "debate-directories") await mkdir(path);
      else await symlink(join(id === "debate-broken" ? base : outside, name), path);
    }
  }
  await symlink(join(root, "debate-directories"), join(root, "debate-internal-link"));

  assert.deepEqual(await listDebates(root), ["debate-artifacts", "debate-broken", "debate-directories"].map((id) => ({
    id, path: join(root, id), hasTranscript: false, hasFinalReport: false, determination: null, status: "unjudged",
  })));
  assert.equal(await readFile(join(outside, "debate.md"), "utf8"), "untouched transcript");
  assert.equal(await readFile(join(outside, "final-report.md"), "utf8"), "untouched report");
});

test("catalog returns empty for an empty or missing root without creating it", async (t) => {
  const root = await fixture(t);
  assert.deepEqual(await listDebates(root), []);
  const missing = join(root, "missing");
  assert.deepEqual(await listDebates(missing), []);
  await assert.rejects(readFile(missing), { code: "ENOENT" });
});

test("catalog propagates errors other than a missing root", async (t) => {
  const root = await fixture(t);
  const file = join(root, "file");
  await writeFile(file, "not a directory");
  await assert.rejects(listDebates(file), { code: "ENOTDIR" });
});

test("determination classification uses only the first nonempty trimmed line", () => {
  for (const [text, expected] of [
    ["STATUS: RESOLVED", "resolved"],
    [" \r\n\t\r\n STATUS: NEEDS_INPUT \r\nDetails", "needs-input"],
    ["\n Respondeo turn failed: timeout\nSTATUS: RESOLVED", "failed"],
    ["Respondeo turn failed:", "failed"],
    ["STATUS: RESOLVED\nSTATUS: NEEDS_INPUT", "resolved"],
    ["", "unknown"],
    [" \n\t\r\n", "unknown"],
    ["status: resolved", "unknown"],
    ["STATUS: needs_input", "unknown"],
    ["STATUS:RESOLVED", "unknown"],
    ["STATUS:  RESOLVED", "unknown"],
    ["STATUS: NEEDS_INPUT extra", "unknown"],
    ["STATUS: RESOLVED.", "unknown"],
    ["# STATUS: RESOLVED", "unknown"],
    ["Preamble\nSTATUS: RESOLVED", "unknown"],
    ["respondeo turn failed: timeout", "unknown"],
    ["Respondeo turn failed", "unknown"],
  ]) {
    assert.equal(classifyDetermination(text), expected, JSON.stringify(text));
  }
});

test("catalog selects the numerically highest positive determination version", async (t) => {
  const root = await fixture(t);
  const path = join(root, "debate-versions");
  await mkdir(path);
  const metadata = async () => {
    const [entry] = await listDebates(root);
    return { determination: entry.determination, status: entry.status };
  };
  await writeFile(join(path, "respondeo.md"), "STATUS: RESOLVED");
  assert.deepEqual(await metadata(), { determination: "respondeo.md", status: "resolved" });
  await writeFile(join(path, "respondeo-2.md"), "STATUS: NEEDS_INPUT");
  await writeFile(join(path, "respondeo-10.md"), "Respondeo turn failed: timeout");
  assert.deepEqual(await metadata(), { determination: "respondeo-10.md", status: "failed" });
  // Leading zeros still denote a positive integer; malformed suffixes do not.
  await writeFile(join(path, "respondeo-011.md"), "malformed\nSTATUS: RESOLVED");
  for (const name of ["respondeo-0.md", "respondeo-000.md", "respondeo--12.md", "respondeo-12.5.md", "respondeo-1e9.md", "respondeo-+12.md", "respondeo-12.md.bak", "respondeo-12.md\n"]) {
    await writeFile(join(path, name), "STATUS: RESOLVED");
  }
  assert.deepEqual(await metadata(), { determination: "respondeo-011.md", status: "unknown" });
  await writeFile(join(path, "respondeo-9007199254740992.md"), "STATUS: RESOLVED");
  await writeFile(join(path, "respondeo-9007199254740993.md"), "STATUS: NEEDS_INPUT");
  assert.deepEqual(await metadata(), { determination: "respondeo-9007199254740993.md", status: "needs-input" });
});

test("catalog ignores symlink and nonregular determinations, including higher versions", async (t) => {
  const base = await fixture(t);
  const root = join(base, "catalog");
  const path = join(root, "debate-links");
  const target = join(base, "outside.md");
  await mkdir(path, { recursive: true });
  await writeFile(target, "STATUS: RESOLVED");
  await symlink(target, join(path, "respondeo.md"));
  await symlink(target, join(path, "respondeo-99.md"));
  await symlink(join(base, "missing"), join(path, "respondeo-100.md"));
  await mkdir(join(path, "respondeo-101.md"));
  await writeFile(join(path, "respondeo-0.md"), "STATUS: RESOLVED");
  let [entry] = await listDebates(root);
  assert.equal(entry.determination, null);
  assert.equal(entry.status, "unjudged");
  await writeFile(join(path, "respondeo-2.md"), "STATUS: NEEDS_INPUT");
  [entry] = await listDebates(root);
  assert.equal(entry.determination, "respondeo-2.md");
  assert.equal(entry.status, "needs-input");
  assert.equal(await readFile(target, "utf8"), "STATUS: RESOLVED");
});

